'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var fibonacci = require( '@stdlib/math/base/special/fibonacci' );
var negaFibonacci = require( '@stdlib/math/base/special/negafibonacci' );
var binet = require( '@stdlib/math/base/special/binet' );
var abs = require( '@stdlib/math/base/special/abs' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var largeNegative = require( './fixtures/python/large_negative.json' );
var largePositive = require( './fixtures/python/large_positive.json' );
var mediumNegative = require( './fixtures/python/medium_negative.json' );
var mediumPositive = require( './fixtures/python/medium_positive.json' );
var smallNegative = require( './fixtures/python/small_negative.json' );
var smallPositive = require( './fixtures/python/small_positive.json' );
var tail = require( './fixtures/python/tail.json' );


// VARIABLES //

var binetf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( binetf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof binetf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', opts, function test( t ) {
	var v = binetf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `+infinity`, the function returns `NaN`', opts, function test( t ) {
	var v = binetf( PINF );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `-infinity`, the function returns `NaN`', opts, function test( t ) {
	var v = binetf( NINF );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` when evaluated at `0`', opts, function test( t ) {
	t.strictEqual( binetf( 0.0 ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for positive small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = smallPositive.x;
	expected = smallPositive.expected;

	// NOTE: the maximum observed error across this domain is 2 ULP; the tolerance is doubled to leave headroom for platform-dependent rounding of `powf`.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 4 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for positive medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = mediumPositive.x;
	expected = mediumPositive.expected;

	// NOTE: the maximum observed error across this domain is 8 ULP; the tolerance is doubled to leave headroom for platform-dependent rounding of `powf`.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 16 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for positive large numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = largePositive.x;
	expected = largePositive.expected;

	// NOTE: the tolerance is larger due to error amplification when the input approaches the overflow threshold of `powf( PHI, x )`; the maximum observed error across this domain is 30 ULP.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 48 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for negative small numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = smallNegative.x;
	expected = smallNegative.expected;

	// NOTE: the maximum observed error across this domain is 9 ULP; the tolerance is larger to leave headroom for platform-dependent rounding of `powf`.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 16 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for negative medium numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = mediumNegative.x;
	expected = mediumNegative.expected;

	// NOTE: the maximum observed error across this domain is 8 ULP; the tolerance is doubled to leave headroom for platform-dependent rounding of `powf`.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 16 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for negative large numbers', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = largeNegative.x;
	expected = largeNegative.expected;

	// NOTE: the tolerance is larger due to error amplification when the input approaches the overflow threshold of `powf( PHI, x )`; the maximum observed error across this domain is 31 ULP.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 48 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function accurately computes Binet\'s formula for values beyond the overflow threshold of `powf( PHI, x )`', opts, function test( t ) {
	var expected;
	var x;
	var v;
	var i;

	x = tail.x;
	expected = tail.expected;

	// NOTE: in this region, the dominant term of Binet's formula is evaluated in log space, and the single-precision rounding of the exponent limits relative accuracy to approximately 10^-5; the maximum observed error across this domain is 144 ULP. Compare `besselj1f`, whose fixtures use a 392 ULP tolerance for the same reason.
	for ( i = 0; i < x.length; i++ ) {
		v = binetf( x[ i ] );
		t.strictEqual( isAlmostSameValuef( v, f32( expected[ i ] ), 200 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns a finite value at the last input which does not overflow `powf( PHI, x )`', opts, function test( t ) {
	var v = binetf( 184.37376403808594 );
	t.notEqual( v, PINF, 'does not overflow' );
	t.notEqual( v, NINF, 'does not overflow' );
	t.end();
});

tape( 'the function returns a finite value at the first input for which `powf( PHI, x )` overflows', opts, function test( t ) {
	var v = binetf( 184.37377929687500 );
	t.notEqual( v, PINF, 'does not overflow' );
	t.ok( isAlmostSameValuef( v, f32( 1.5217946688125778e38 ), 96 ), 'within 96 ULP of the float64 reference' );
	t.end();
});

tape( 'the function returns a finite value at the last input which does not overflow', opts, function test( t ) {
	var v = binetf( 186.04 );
	t.ok( isAlmostSameValuef( v, f32( 3.3929353860553163e38 ), 200 ), 'within 200 ULP of the float64 reference' );
	t.end();
});

tape( 'the function returns `+infinity` at the first input which overflows', opts, function test( t ) {
	t.strictEqual( binetf( 186.1 ), PINF, 'equals +infinity' );
	t.end();
});

tape( 'the function returns a finite value for large negative inputs whose result is representable', opts, function test( t ) {
	var v = binetf( -186.04 );
	t.ok( isAlmostSameValuef( v, f32( -3.3661810623712355e38 ), 48 ), 'within 48 ULP of the float64 reference' );
	t.end();
});

tape( 'the function returns `-infinity` for large negative inputs whose dominant term overflows', opts, function test( t ) {
	t.strictEqual( binetf( -200.0 ), NINF, 'equals -infinity' );
	t.end();
});

tape( 'the function returns a subnormal value at negative half-integers near the underflow threshold', opts, function test( t ) {
	// At negative half-integers, `cospi(x)` is exactly zero, so the dominant (overflowing) term vanishes and the result equals `phi^(-|x|)/sqrt(5)`:
	t.strictEqual( binetf( -200.5 ), 5.605193857299268e-43, 'equals expected value' );
	t.strictEqual( binetf( -300.5 ), 0.0, 'underflows to zero' );
	t.end();
});

tape( 'the function does not return `NaN` for any finite input', opts, function test( t ) {
	var v;
	var x;
	for ( x = -400.0; x <= 400.0; x += 0.5 ) {
		v = binetf( x );
		t.strictEqual( isnanf( v ), false, 'does not return NaN' );
	}
	t.end();
});

tape( 'for nonnegative integers, the function approximates the nth Fibonacci number', opts, function test( t ) {
	var expected;
	var v;
	var i;

	// NOTE: the range is capped at 36, as `fibonacci(37)` is not exactly representable in single precision.
	for ( i = 0; i <= 36; i++ ) {
		v = binetf( i );
		expected = f32( fibonacci( i ) );
		t.strictEqual( isAlmostSameValuef( v, expected, 8 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'for nonpositive integers, the function approximates the nth negafibonacci number', opts, function test( t ) {
	var expected;
	var v;
	var i;

	// NOTE: the range is capped at -36, as `negafibonacci(-37)` is not exactly representable in single precision.
	for ( i = 0; i >= -36; i-- ) {
		v = binetf( i );
		expected = f32( negaFibonacci( i ) );
		t.strictEqual( isAlmostSameValuef( v, expected, 8 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function is absolutely accurate near `x = 0`, where the two terms of Binet\'s formula nearly cancel', opts, function test( t ) {
	var v;
	var x;

	// NOTE: relative error is inherently unbounded near cancellation points, so we assert absolute error against the float64 reference instead.
	for ( x = -0.5; x <= 0.5; x += 0.01 ) {
		v = binetf( x );
		t.strictEqual( abs( v - binet( x ) ) <= 1e-6, true, 'absolute error is within 1e-6' );
	}
	t.end();
});
